  "conics-ellipse-diagram": "<div class=\"mx-auto max-w-sm rounded-xl border bg-indigo-50/40 p-4 dark:bg-indigo-950/20\"><svg viewBox=\"0 0 290 200\" class=\"w-full\" role=\"img\" aria-label=\"An ellipse centred at the origin with semi-major axis a along the x-axis, semi-minor axis b along the y-axis, and two foci on the x-axis. A point P is joined to both foci, illustrating that the two focal distances add to 2a.\"><line x1=\"23\" y1=\"100\" x2=\"267\" y2=\"100\" class=\"stroke-slate-300 dark:stroke-slate-600\" stroke-width=\"0.7\"></line><line x1=\"145\" y1=\"24\" x2=\"145\" y2=\"176\" class=\"stroke-slate-300 dark:stroke-slate-600\" stroke-width=\"0.7\"></line><ellipse cx=\"145\" cy=\"100\" rx=\"110\" ry=\"64\" class=\"fill-indigo-500/10 stroke-indigo-600 dark:stroke-indigo-300\" stroke-width=\"2\"></ellipse><circle cx=\"55.534923014619835\" cy=\"100\" r=\"3.2\" class=\"fill-rose-500\"></circle><circle cx=\"234.46507698538016\" cy=\"100\" r=\"3.2\" class=\"fill-rose-500\"></circle><text x=\"55.534923014619835\" y=\"115\" class=\"fill-rose-600 dark:fill-rose-300\" font-size=\"8.5\" text-anchor=\"middle\">F₁(−c,0)</text><text x=\"234.46507698538016\" y=\"115\" class=\"fill-rose-600 dark:fill-rose-300\" font-size=\"8.5\" text-anchor=\"middle\">F₂(c,0)</text><line x1=\"55.534923014619835\" y1=\"100\" x2=\"213.37709650977308\" y2=\"150.13292221615893\" class=\"stroke-emerald-500\" stroke-width=\"1.2\"></line><line x1=\"234.46507698538016\" y1=\"100\" x2=\"213.37709650977308\" y2=\"150.13292221615893\" class=\"stroke-emerald-500\" stroke-width=\"1.2\"></line><circle cx=\"213.37709650977308\" cy=\"150.13292221615893\" r=\"3\" class=\"fill-emerald-600\"></circle><text x=\"217.37709650977308\" y=\"162.13292221615893\" class=\"fill-emerald-700 dark:fill-emerald-300\" font-size=\"8.5\">P</text><text x=\"200\" y=\"96\" class=\"fill-slate-500\" font-size=\"9\">a</text><text x=\"149\" y=\"68\" class=\"fill-slate-500\" font-size=\"9\">b</text><text x=\"70\" y=\"194\" class=\"fill-emerald-700 dark:fill-emerald-300\" font-size=\"8.5\">PF₁ + PF₂ = 2a · c² = a² − b²</text></svg></div>",
